<template><ForgeDialog title="Regex tester" description="Test a regular expression against sample text." eyebrow="WORKSPACE / CODE" wide @close="emit('close')"><div class="regex-test"><div class="regex-input"><input v-model="pattern" placeholder="Pattern, e.g. ^[A-Z][a-z]+$" /><select v-model="flags"><option value="g">Global</option><option value="gi">Global + case insensitive</option><option value="m">Multiline</option><option value="im">Case insensitive + multiline</option></select></div><textarea v-model="sample" rows="10" placeholder="Paste sample text here" /><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p><div class="match-summary"><b>{{ matches.length }}</b> matches</div><div class="matches"><code v-for="(match,index) in matches" :key="index">{{ index + 1 }}. {{ match }}</code><span v-if="!matches.length&&!error">No matches.</span></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
const emit=defineEmits<{close:[]}>(); const pattern=ref(''); const flags=ref('g'); const sample=ref(''); const error=computed(()=>{if(!pattern.value)return '';try{new RegExp(pattern.value,flags.value);return ''}catch(e){return e instanceof Error?e.message:'Invalid expression'}}); const matches=computed(()=>{if(!pattern.value||error.value)return [];try{const re=new RegExp(pattern.value,flags.value.includes('g')?flags.value:flags.value+'g');return Array.from(sample.value.matchAll(re),m=>m[0]).slice(0,500)}catch{return []}})
</script>
<style scoped>.regex-test{display:grid;gap:12px}.regex-input{display:flex;gap:8px}.regex-input input,.regex-input select,.regex-test textarea{padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.regex-input input{flex:1}.regex-test textarea{resize:vertical}.match-summary{padding:10px;border:1px solid var(--pqt-border);border-radius:7px;color:var(--pqt-text-muted)}.match-summary b{color:var(--pqt-accent)}.matches{display:grid;gap:5px;max-height:180px;overflow:auto}.matches code{padding:7px;background:var(--pqt-canvas);border-radius:5px;color:#b3d7ce;font:11px var(--pqt-font-mono)}</style>
